definition.raw:
The {\em vertical Lagrange density} of $\pi$ is the map
$e^v_\Phi:\Gamma(\pi)\rightarrow \cC^\infty(M,\R)$ defined, for every
$s\in \Gamma(\pi)$, as follows:
\begin{equation*}
e^v_\bPhi(g,h,s)\stackrel{{\rm def.}}{=} \frac{1}{2}\mathrm{Tr}_{g} s^\ast_v(h_V)+\bPhi^s~~,
\end{equation*} 
where $s^\ast_v(h_V)$ is the vertical first fundamental form of $s$
(see Appendix \ref{app:submersions}) and $\bPhi^s= \bPhi\circ s\in
\cC^\infty(M,\R)$. Let:
\begin{equation*}
e^v(g,h,s)\stackrel{{\rm def.}}{=} e^v_0(g,h,s)=\frac{1}{2}\mathrm{Tr}_{g} s^\ast(h_V)~~.
\end{equation*}

The {\em section sigma model} defined by $\pi$ and $\bPhi$ has action
functional $S_{\sc}\colon\Met_{3+n,1}(E)\times \Gamma(\pi)\rightarrow
\R$ given by:
\begin{equation}
\label{Ssc}
S_{\sc,U}[g, h, s]=-\int_U\nu_M(g)e^v_\bPhi(g,h,s)
\end{equation}
for any relatively-compact subset $U\subset M$.

The {\em vertical tension field} of $s\in \Gamma(\pi)$ is defined
through:
\begin{equation*}
\label{tensionvert}
\tau^v(g, h, s)\stackrel{{\rm def.}}{=} \mathrm{Tr}_{g}\nabla^v \dd^v s \in \Gamma(M,V^s)~~.
\end{equation*}

A taming $\bJ$ of $(\bcS,\bomega,\bD)$ is called {\em vertical} if it
is $\mT$-invariant, which means that it satisfies:
\begin{equation*}
\mT_{\gamma}\circ J_{\gamma(0)}=J_{\gamma(1)}\circ \mT_\gamma\, , \qquad \forall\, \gamma\in \cP(M)\, .
\end{equation*}

The {\em extended holonomy group} of $\bcD$ at the point $m\in M$ is the
subgroup of $\mathrm{Aut}(\cD_m)$ defined through:
\begin{equation*}
\mG_m\stackrel{{\rm def.}}{=} \{\mT_{\gamma}\,|\, \gamma\in \cP(M) , \gamma(0)=\gamma(1)=m\}\subset \mathrm{Aut}(\cD_m)\, .
\end{equation*}

The \emph{fundamental bundle form} $\bTheta$ of $\bcD$ is
the $End(\bcS)$-valued one-form defined on $E$ as follows:
\begin{equation*}
\bTheta \stackrel{{\rm def.}}{=} \bD^{\ad} \bJ \in \Omega^{1}(E,End(\bcS))\, .
\end{equation*}

The \emph{fundamental bundle field} $\bPsi$ of $\bcD$ is
the $End(\bcS)$-valued vector field defined on $E$ as follows:
\begin{equation*}
\bPsi \stackrel{{\rm def.}}{=} \left(\sharp_{h}\otimes \mathrm{Id}_{End(\bcS)} \right)\circ D^{\ad} \bJ \in \Gamma(E,V\otimes End(\bcS))\, .
\end{equation*}

Let $\bcD=(\pi,\bPhi, \bXi)$ be a scalar-electromagnetic bundle
with associated Kaluza-Klein space $\pi\colon (E,h)\to
(M,g)$ and let $s\in \Gamma(\pi)$ be a section of $\pi$. An {\em
electromagnetic field strength} is a two-form
$\bcV\in \Omega^2(M,\bcS^s)$ having the following properties:
\begin{enumerate}[1.]
\itemsep 0.0em
\item $\bcV$ is positively-polarized with respect to $\bJ^s$, i.e. the
  following relation is satisfied:
\begin{equation*}
\ast_g \bcV=-\bJ^s\bcV\, .
\end{equation*}
\item $\bcV$ satisfies the {\em electromagnetic equation} with respect
  to $s$:
\begin{equation}
\label{GaugeEOM}
\dd_{\bD^s} \bcV=0~~.
\end{equation}
\end{enumerate}

The {\em solution sheaf} $\Sol_{\bcD}$ of a GESM theory associated to
a scalar-electromagnetic bundle $\bcD = (\pi,\bPhi,\bXi)$ is the sheaf
of sets given by:
\begin{equation*}
\bSol_{\bcD}(U)\stackrel{{\rm def.}}{=} \{(g,s,\bcV)\in \Conf_{\bcD}(U) \,\, |\,\, \cE_{E}(g,s,\bcV) = 0\, , \quad  \cE_{S}(g,s,\bcV) = 0\, , \quad \cE_{K}(g,s,\bcV) = 0\}
\end{equation*}
for every open set $U\subset M$.

Let $\pi:E\rightarrow M$ be a surjective submersion and $h$, $g$ be
pseudo-Riemannian metrics on $E$ and $M$ respectively. We say that
$\pi$ is a {\em pseudo-Riemannian submersion from} $(E,h)$ to $(M,g)$
if the following two conditions are satisfied:
\begin{enumerate}[1.]
\item $h$ is vertically non-degenerate with respect to $\pi$, i.e. the
  restriction of $h$ to $V$ is non-degenerate.
\item The based isomorphism $(\dd\pi)_H:H\stackrel{\sim}{\rightarrow}
  (TM)^\pi$ is an isometry from $(H,h_H)$ to $((TM)^\pi,g^\pi)$.
\end{enumerate}

Let $g\in \Met(M)$ be a pseudo-Riemannian metric on $M$,
$\fh\in \Met(V)$ be a pseudo-Riemannian metric on $V$ and
$H\in \cH(\pi)$ be a horizontal distribution for $\pi$. The {\em
Kaluza-Klein metric} determined by $g$, $\fh$ and $H$ is the
pseudo-Riemannian metric on $E$ defined through:
\begin{equation}
\label{KK}
h_{g, \fh, H}(X,Y)\stackrel{{\rm def.}}{=} \fh(X_V,Y_V)+g^\pi( (\dd \pi)_H
(X_H),(\dd \pi)_H(Y_H))\, , \quad \forall\, X,Y\in \cX(E)\, .
\end{equation}

The {\em Kaluza-Klein correspondence} of $\pi$ is the map
$\mathcal{K}_\pi:\Met(M)\times \Met(V)\times\cH(\pi)\rightarrow
\Met_\pi(E)$ defined through:
\begin{equation*}
\mathcal{K}_\pi(g,\fh,H)\stackrel{{\rm def.}}{=} h_{g,\fh,H}\in \Met_{\pi,g}(E)\subset \Met_\pi(E)\, .
\end{equation*}

theorem.raw:
\label{thm:equivalence}
Let $\bcD = (\pi,\bPhi,\bXi)$ be an scalar-electromagnetic bundle of
type $\cD=(\mathcal{M},\cS,\omega,D,J)$, whose Kaluza-Klein space is
integrable. Then any special trivializing atlas
$(U_\alpha,\mq_\alpha)_{\alpha\in I}$ of $\bcD$ induces bijections:
\begin{equation*}
\mathfrak{C}_\alpha \colon \bConf_{\bcD}(U_{\alpha})\xrightarrow{\sim}  \Conf_{\cD}(U_{\alpha})
\end{equation*}
which restrict bijections:
\begin{equation*}
\mathfrak{C}_\alpha \colon \bSol_{\bcD}(U_{\alpha}) \xrightarrow{\sim} \Sol_{\cD}(U_{\alpha})~~.
\end{equation*}

proposition.raw:
Integrable scalar bundles defined over $(M,g)$ and having type
$(\mathcal{M},\cG,\Phi)$ are classified up to isomorphism by the points of the
character variety:
\begin{equation*}
\mathcal{M}_{\Iso(\mathcal{M},\cG,\Phi)}(M)\stackrel{{\rm def.}}{=} {\rm Hom}(\pi_1(M),\Iso(\mathcal{M},\cG,\Phi))/\Iso(\mathcal{M},\cG,\Phi)~~.
\end{equation*}

The vertical density $e^v(s)$ differs from $e(s)$ by a constant and we
have $\tau^v(s)=P_V\circ\tau(s)$. Moreover, the critical points
of \eqref{Ssc} with respect to $s\in \Gamma(\pi)$ are solutions of the
equation:
\begin{equation}
\label{sceom}
\tau^v(s)=-(\grad_h\bPhi)^s\, .
\end{equation}

Let $\bcD = (\pi,\bPhi,\bXi)$ be a scalar-electromagnetic structure of
type:
\begin{equation*}
\cD = (\mathcal{M}, \cG, \Phi,\cS,D,\omega,J)
\end{equation*}
Then the isomorphism type of the fundamental bundle form $\bTheta$
of $\bcD$ is given by:
\begin{equation*}
\Theta \stackrel{{\rm def.}}{=} \Theta_{m_{0}} = D^{\ad}J \in \Omega^{1}(\mathcal{M},End(\cS))~~,
\end{equation*}
while the isomorphism type of the fundamental bundle field $\bPsi$
of $\bcD$ is given by:
\begin{equation*}
\Psi \stackrel{{\rm def.}}{=} \Psi_{m_{0}} = \left(\sharp_{\cG}\otimes \mathrm{Id}_{End(\cS)} \right) D^{\ad}J \in \mathfrak{X}(\mathcal{M},End(\cS)) \, .
\end{equation*}

remark.raw:
When $\bPhi=0$, equation \eqref{sceom} becomes the {\em vertical
pseudoharmonic equation}:
\begin{equation*}
\label{pseudoharm}
\tau^v(s)=0
\end{equation*}
and its solutions are called {\em pseudoharmonic sections} of $\pi$.

\label{remark:Tgammaction}
Equation \eqref{eq:isoTheta} follows from the following
computation\footnote{Equation \eqref{eq:isoPsi} can be proved
  similarly.}:
\begin{equation*}
\mT_{\gamma} \cdot \Theta_{m_{0}} = \mT_{\gamma}\cdot D^{\ad}_{m_{0}}(\mT^{-1}_{\gamma}\cdot\mT_{\gamma}\cdot J_{m_{0}}) = \mT_{\gamma}\cdot D^{\ad}_{m_{0}}(\mT^{-1}_{\gamma}\cdot J_{m}) = D^{\ad}_{m} J_{m} = \Theta_{m}\, ,
\end{equation*}
where we have used the fact that $\mT_{\gamma}$ preserves $D_{m_{0}}$ and $D_{m}$, i.e.:
\begin{equation}
\label{eq:D0m}
D^{\ad}_{m}(\xi)  =  \mT_{\gamma}\cdot D^{\ad}_{m_{0}} (\mT^{-1}_{\gamma}\cdot\xi) = \mT_{\gamma}\cdot D^{\ad}_{m_{0}} (\mT^{-1}_{\gamma}\circ\xi \circ T_{\gamma})\, , \quad\forall\,\, \xi\in\Gamma(E_{m},\cS_{m})\, ,
\end{equation}
as well as the relations:
\begin{eqnarray}
\label{eq:J0m}
& (\mT_{\gamma}\cdot J_{m_{0}})(\xi) = \mT_{\gamma}\cdot J_{m_{0}}(\mT^{-1}_{\gamma}\cdot\xi) = \mT_{\gamma}\cdot (J_{m_{0}} \circ\mT^{-1}_{\gamma}\circ \xi \circ T_{\gamma}) \nonumber\\
& = \mT_{\gamma}\circ (J_{m_{0}} \circ\mT^{-1}_{\gamma}\circ \xi \circ T_{\gamma})\circ T^{-1}_{\gamma} = \mT_{\gamma}\circ J_{m_{0}} \circ\mT^{-1}_{\gamma}\circ \xi = J_{m}(\xi)\, ,
\end{eqnarray}
which hold for all $\xi\in \Gamma(E_{m},\cS_{m})$. Notice that the
$\mT_{\gamma}$-action symbols $``\cdot"$ and $``\circ"$ in equations
\eqref{eq:D0m} and \eqref{eq:J0m} have a different meaning depending
on the step and the sections involved. In equation \eqref{eq:D0m} we
have:
\begin{equation*}
D^{\ad}_{m_{0}} (\mT^{-1}_{\gamma}\circ\xi \circ T_{\gamma}) \in \Omega^{1}(E_{m_{0}},\cS_{m_{0}})
\end{equation*}
and evaluating on a vector field $X\in\mathfrak{X}(E_{m})$ we obtain:
\begin{equation*}
\iota_{X} D^{\ad}_{m}(\xi) = \mT_{\gamma}\circ \left(\iota_{T^{-1}_{\gamma\ast}X} D^{\ad}_{m_{0}} (\mT^{-1}_{\gamma}\circ\xi \circ T_{\gamma})\right)\circ T^{-1}_{\gamma}\in \Gamma(E_{m},\cS_{m})\, .
\end{equation*}
Likewise, in the second step of equation \eqref{eq:J0m} we use:
\begin{equation*}
\mT^{-1}_{\gamma}\cdot\xi = \mT^{-1}_{\gamma}\circ \xi \circ T_{\gamma}\in \Gamma(E_{m_{0}},\cS_{m_{0}}) \, , \quad \xi\in \Gamma(E_{m},\cS_{m})\, ,
\end{equation*}
where $\mT^{-1}_{\gamma}$ in the left hand side acts through
$``\cdot"$ as the isomorphism of modules:
\begin{equation*}
\mT^{-1}_{\gamma}\colon \Gamma(E_{m},\cS_m) \to \Gamma(E_{m_{0}},\cS_{m_{0}})\, ,
\end{equation*}
whereas $\mT^{-1}_{\gamma}$ in the right-hand-side acts through $``\circ"$
as composition with the unbased automorphism
$\mT^{-1}_{\gamma}\colon \cS_{m}\to \cS_{m_{0}}$ of vector bundles
covering $T^{-1}_{\gamma}$.

