The 
GESM theory associated to $\bcD$ is defined by the following set of
partial differential equations on $(M,g)$:
\begin{itemize}
\item The Einstein equations\footnote{We denote Einstein's gravitational constant by $\kappa$.}:	
\begin{equation}
\cE_{E}(g,s,\bcV) \stackrel{{\rm def.}}{=} \G(g) -\kappa\,\mathrm{T}(g,s,\bcV) = 0\, ,
\end{equation}
where $\mathrm{T}(g,s,\bcV)\in\Gamma(M,S^{2}T^{\ast}M)$ is the
energy-momentum tensor of the theory, which is given by:
\begin{equation*}
\mathrm{T}(g,s,\bcV)  = g\, e^{v}_{0}(g,h,s) - h^{s}_{V} + \frac{g}{2} \bPhi^{s}  + 2~\bcV \loslash \bcV \, .
\end{equation*} 

\item The scalar equations:
\begin{equation}
\label{sc}
\cE_{S}(g,s,\bcV) \stackrel{{\rm def.}}{=} \tau^{v}(g,h,s) + (\grad_{h} \bPhi)^{s}- \frac{1}{2} (\ast \bcV , \bPsi^s\bcV) = 0\, .
\end{equation}
\item The electromagnetic (or Maxwell) equations:
\begin{equation}
\cE_{K}(g,s,\bcV) \stackrel{{\rm def.}}{=}\dd_{\bD^s} \bcV=0\, .
\end{equation}	

\end{itemize}

