In this case, relation \eqref{bgdef} gives: 
\begin{equation}
\label{bgflat}
{\hat q}_\beta|_{E_{\alpha\beta}}=\bg_{\alpha\beta}\circ {\hat q}_\alpha|_{E_{\alpha\beta}}~~\forall \alpha,\beta\in I~~,
\end{equation}
where $E_{\alpha\beta}\stackrel{{\rm def.}}{=} E|_{\pi^{-1}(U_{\alpha\beta})}$ and we
define $\bg_{\alpha\beta}\stackrel{{\rm def.}}{=} \mathrm{id}_\mathcal{M}$ when
$U_{\alpha\beta}=\emptyset$.

\begin{remark}
Suppose that the integrable Kaluza-Klein space $\pi$ is endowed with a
vertical potential $\bPhi$ whose restriction to $\mathcal{M}$ we denote by
$\Phi$. Then the constant transition functions in a special
trivializing atlas satisfy $\bg_{\alpha\beta}\in \Iso(\mathcal{M},\cG,\Phi)$.
\end{remark}

\begin{remark}
When $\bPhi=0$, equation \eqref{sceom} becomes the {\em vertical
pseudoharmonic equation}:
\begin{equation*}
\label{pseudoharm}
\tau^v(s)=0
\end{equation*}
and its solutions are called {\em pseudoharmonic sections} of $\pi$. 
\end{remark}	

\noindent 
Notice that \eqref{Ssc} is extremized only with respect to vertical
variations of $s$, since $s$ is subject to the section constraint
$\pi\circ s=\mathrm{id}_M$. As a consequence, a section which is
pseudo-harmonic as an unconstrained map from $(M,g)$ to $(E,h)$ is a
pseudo-harmonic section, but not every pseudo-harmonic section is
pseudo-harmonic as an unconstrained map from $(M,g)$ to $(E,h)$.

\begin{proof}
Given $(g_\alpha,s_\alpha,\bcV_\alpha)\in \bConf_{\bcD}(U_\alpha)$, we set:
\begin{equation*}
\mathfrak{C}_{\alpha}(g_{\alpha},s_{\alpha},\bcV_{\alpha})\stackrel{{\rm def.}}{=} (g_{\alpha},\varphi^\alpha,\cV^\alpha)~~,
\end{equation*}
where $\varphi^\alpha$ and $\cV_\alpha$ are defined as follows:
\begin{itemize}
\item As explained in Subsection \ref{spectrivgauge}, the special
  trivializing atlas $(U_\alpha,\mq_\alpha)$ is underlined by a
  special trivializing atlas $(U_\alpha,q_\alpha)$ of the fiber bundle
  $\pi:E\rightarrow M$, whose trivializing maps are diffeomorphisms
  $q_\alpha:E_\alpha\stackrel{{\rm def.}}{=} \pi^{-1}(U_\alpha)\rightarrow
  E_\alpha^0=U_\alpha\times \mathcal{M}$. This allows us to define smooth maps
  $\varphi^{\alpha}\in \cC^\infty(U_\alpha,\mathcal{M})$ such that
  $s_\alpha=q_\alpha^{-1}\circ \graph(\varphi^\alpha)$ as in
  Subsection \ref{subsec:sigmaUfold}:
\begin{equation*}
\varphi^{\alpha}\stackrel{{\rm def.}}{=} \hat{q}_{\alpha}\circ s_{\alpha} = \ungraph(q_\alpha\circ s_\alpha)=p^{0}_{\alpha}\circ q_{\alpha}\circ s_{\alpha}~~.
\end{equation*}
\item As explained in Subsection \ref{spectrivgauge}, the maps
  $\mq_\alpha:(\bcS_\alpha, \bomega_\alpha, \bD_\alpha,
  \bJ_\alpha)\stackrel{\sim}{\rightarrow}
  (\bcS^0_{\alpha},\bomega^0_{\alpha}, \bD^0_{\alpha},
  \bJ^0_{\alpha})=(\cS^{p_\alpha^0}, \omega^{p_\alpha^0},
  D^{p_\alpha^0}, J^{p_\alpha^0})$ are unbased isomorphisms of
  electromagnetic structures which linearize the diffeomorphisms
  $q_\alpha$. They induce isomorphisms:
\begin{equation*}
\mq_\alpha^{(s_\alpha)}:(\bcS_\alpha^{s_\alpha}, \bomega_\alpha^{s_\alpha}, \bD_\alpha^{s_\alpha},
\bJ_\alpha^{s_\alpha})\stackrel{\sim}{\rightarrow}
(\cS^{\varphi^{\alpha}}, \omega^{\varphi^{\alpha}}, D^{\varphi^{\alpha}},
J^{\varphi^{\alpha}})\stackrel{{\rm def.}}{=} \cD^{\varphi^\alpha}\, ,
\end{equation*}
where we noticed that
$(\bcS^0_{\alpha})^{s_\alpha}=(\cS^{p^0_{\alpha}})^{s_\alpha}=\cS^{\varphi^\alpha}$ and
we used the fact that the horizontal part of $\bD^0_{\alpha}$ is the
trivial flat connection. This allows us to identify $\bcV_\alpha$ with the
$\cS^{\varphi^{\alpha}}$-valued two-form defined on $U_\alpha$
through:
\begin{equation}
\label{cVlocdef}
\cV^{\alpha}\stackrel{{\rm def.}}{=} \mq_\alpha^{(s_\alpha)}(\bcV_\alpha)\in \Omega^2(U_\alpha,\cS^{\varphi^{\alpha}})\, .
\end{equation}
The relation $J^{\varphi^{\alpha}}\circ
\mq_\alpha^{(s_\alpha)}=\mq_\alpha^{(s_\alpha)} \circ \bJ_\alpha^{s_\alpha}$ implies:
\begin{equation}
\label{eomcorresp}
\bcV_\alpha\in \Omega^{2+,s_\alpha}_{g_\alpha, \bcS^{s_\alpha}_{\alpha},\bJ^{s_\alpha}_{\alpha}}(U_\alpha)~~\mathrm{iff}~~ \cV^{\alpha}\in \Omega^{2+,\varphi^{\alpha}}_{g_{\alpha},\cS^{\varphi^{\alpha}},J^{\varphi^{\alpha}}}(U_\alpha)~~
\end{equation}
\end{itemize}
\noindent
The fact that $\mathfrak{C}_\alpha$ is bijective follows immediately
from its definition.  The fact that $\mathfrak{C}_{\alpha}$ induces a
bijection between solution sets follows from the equivalences:
\begin{eqnarray}
\label{equiv}
& \cE^{\bcD}_{E}(g_{\alpha},s_{\alpha},\bcV_{\alpha}) = 0\Leftrightarrow \cE^{\cD}_{E}(g_{\alpha},\phi^\alpha,\cV_\alpha)=0~~,~~\cE^{\bcD}_{S}(g_{\alpha},s_{\alpha},\bcV_{\alpha}) = 0\Leftrightarrow 
\cE^{\cD}_{S}(g_{\alpha},\phi^\alpha,\cV_\alpha)=0 \nonumber \\ 
& \cE^{\bcD}_{K}(g_{\alpha},s_{\alpha},\bcV_{\alpha}) = 0\Leftrightarrow \cE^{\cD}_{K}(g_{\alpha},\phi^\alpha,\cV_\alpha)=0~~.
\end{eqnarray}
This follows by a direct but somewhat lengthy computation using
relations \eqref{eomcorresp}, which we will not reproduce here. For
example, it is easy to see that the relation
$\dd_{D^{\varphi^{\alpha}}}\circ\mq_\alpha^{(s_\alpha)}=\mq_\alpha^{(s_\alpha)}\circ\dd_{\bD^{s_\alpha}}$
implies that the electromagnetic equation
$\dd_{\bcD^{s_\alpha}}\bcV_\alpha=0$ is equivalent with the equation
$\dd_{D^{\varphi^{\alpha}}}\cV^{\alpha}=0$.
\end{proof}

\begin{remark}
Together with the results of \cite{GESM}, Theorem
\ref{thm:equivalence} shows that a GESM theory represents an
admissible global extension of the locally-formulated bosonic theories
considered by physicists in the context of supergravity.
\end{remark}

